    <script>
      const realmLevels = {
        炼气期: [
          "一层",
          "二层",
          "三层",
          "四层",
          "五层",
          "六层",
          "七层",
          "八层",
          "九层",
          "十层",
        ],
        筑基期: ["前期", "中期", "后期", "大圆满"],
        金丹期: ["前期", "中期", "后期", "大圆满"],
        元婴期: ["前期", "中期", "后期", "大圆满"],
        化神期: ["前期", "中期", "后期", "大圆满"],
        炼虚期: ["前期", "中期", "后期", "大圆满"],
        合体期: ["前期", "中期", "后期", "大圆满"],
        大乘期: ["前期", "中期", "后期", "大圆满"],
        渡劫期: [],
        真仙境: [
          "一重天",
          "二重天",
          "三重天",
          "四重天",
          "五重天",
          "六重天",
          "七重天",
          "八重天",
          "九重天",
          "十重天",
          "大圆满",
        ],
      };

      document.getElementById("realm").addEventListener("change", function () {
        const realmLevelSelect = document.getElementById("realmLevel");
        const selectedRealm = this.value;

        realmLevelSelect.innerHTML = '<option value="">请选择</option>';

        if (selectedRealm && realmLevels[selectedRealm]) {
          const levels = realmLevels[selectedRealm];

          if (levels.length === 0) {
            realmLevelSelect.disabled = true;
            realmLevelSelect.required = false;
          } else {
            realmLevelSelect.disabled = false;
            realmLevelSelect.required = true;
            levels.forEach((level) => {
              const option = document.createElement("option");
              option.value = level;
              option.textContent = level;
              realmLevelSelect.appendChild(option);
            });
          }
        } else {
          realmLevelSelect.disabled = true;
          realmLevelSelect.required = false;
        }
      });

      document
        .getElementById("characterForm")
        .addEventListener("submit", async function (e) {
          e.preventDefault();

          const data = {
            name: document.getElementById("name").value,
            gender: document.getElementById("gender").value,
            age: document.getElementById("age").value,
            realm: document.getElementById("realm").value,
            realmLevel: document.getElementById("realmLevel").value,
            spiritRoot: document.getElementById("spiritRoot").value,
            appearance: document.getElementById("appearance").value,
            faction: document.getElementById("faction").value,
            position: document.getElementById("position").value,
            domain: document.getElementById("domain").value,
            region: document.getElementById("region").value,
            scene: document.getElementById("scene").value,
            sceneType: document.getElementById("sceneType").value,
            bodyStatus: document.getElementById("bodyStatus").value,
            background: document.getElementById("background").value,
            startDirection: document.getElementById("startDirection").value,
          };

          let result = "这是角色设定，请根据这些信息开始故事。\n\n";
          result += "【基础信息】\n";
          result += `姓名：${data.name}\n`;
          result += `性别：${data.gender}\n`;
          result += `年龄：${data.age}岁\n`;
          result += `修为境界：${data.realm}`;
          if (data.realmLevel) {
            result += `${data.realmLevel}`;
          }
          result += "\n";
          if (data.spiritRoot) {
            result += `灵根属性：${data.spiritRoot}\n`;
          }
          if (data.appearance) {
            result += `外貌描写：${data.appearance}\n`;
          }

          result += "\n【势力归属】\n";
          result += `所属势力：${data.faction}\n`;
          if (data.position) {
            result += `宗门身份：${data.position}\n`;
          }

          result += "\n【当前位置】\n";
          result += `所在大域：${data.domain}\n`;
          if (data.region) {
            result += `所在区域：${data.region}\n`;
          }
          if (data.scene) {
            result += `具体场景：${data.scene}\n`;
          }
          result += `场景类型：${data.sceneType}\n`;

          result += "\n【当前状态】\n";
          result += `身体状态：${data.bodyStatus}\n`;

          if (data.background) {
            result += "\n【背景故事】\n";
            result += data.background + "\n";
          }

          if (data.startDirection) {
            result += "\n【开局方向】\n";
            result += data.startDirection + "\n";
          }

          document.getElementById("resultText").textContent = result;
          document.getElementById("characterForm").style.display = "none";
          document.getElementById("resultContainer").classList.add("show");

          try {
            await saveToWorldbook(data, result);
          } catch (error) {
            console.error("保存到世界书失败:", error);
            alert("保存到世界书失败，请检查是否在酒馆中打开此页面");
          }
        });

      async function saveToWorldbook(data, textResult) {
        if (typeof window.TavernHelper === "undefined") {
          console.warn("未检测到 TavernHelper，跳过保存到世界书");
          return;
        }

        const charWorldbooks =
          window.TavernHelper.getCharWorldbookNames("current");
        const primaryWorldbook = charWorldbooks.primary;

        if (!primaryWorldbook) {
          console.warn("当前角色卡没有绑定主世界书");
          return;
        }

        const yamlContent = `用户信息:
  基础信息:
    姓名: ${data.name}
    性别: ${data.gender}
    年龄: ${data.age}
    修为境界: ${data.realm}${data.realmLevel ? data.realmLevel : ""}${
          data.spiritRoot ? `\n    灵根属性: ${data.spiritRoot}` : ""
        }${
          data.appearance
            ? `\n    外貌描写: |\n      ${data.appearance.replace(
                /\n/g,
                "\n      "
              )}`
            : ""
        }

  势力归属:
    所属势力: ${data.faction}${
          data.position ? `\n    宗门身份: ${data.position}` : ""
        }

  当前位置:
    所在大域: ${data.domain}${
          data.region ? `\n    所在区域: ${data.region}` : ""
        }${data.scene ? `\n    具体场景: ${data.scene}` : ""}
    场景类型: ${data.sceneType}

  当前状态:
    身体状态: ${data.bodyStatus}${
          data.background
            ? `\n\n  背景故事: |\n    ${data.background.replace(
                /\n/g,
                "\n    "
              )}`
            : ""
        }${
          data.startDirection
            ? `\n\n  开局方向: |\n    ${data.startDirection.replace(
                /\n/g,
                "\n    "
              )}`
            : ""
        }`;

        const allEntries = await window.TavernHelper.getLorebookEntries(
          primaryWorldbook
        );
        const existingEntry = allEntries.find(
          (entry) => entry.comment === "用户信息"
        );

        if (existingEntry) {
          await window.TavernHelper.setLorebookEntries(primaryWorldbook, [
            {
              uid: existingEntry.uid,
              content: yamlContent,
              position: 0,
              order: 10,
            },
          ]);
        } else {
          await window.TavernHelper.setLorebookEntries(primaryWorldbook, [
            {
              comment: "用户信息",
              content: yamlContent,
              constant: true,
              position: 0,
              order: 10,
            },
          ]);
        }

        await window.TavernHelper.createChatMessages(
          [
            {
              role: "user",
              message: textResult,
            },
          ],
          {
            insert_at: "end",
            refresh: "all",
          }
        );

        console.log("用户信息已保存到世界书和聊天记录");

        await window.TavernHelper.generate({});

        console.log("已触发AI回复");
      }

      function copyResult() {
        const text = document.getElementById("resultText").textContent;
        navigator.clipboard.writeText(text).then(() => {
          const button = event.target;
          const originalText = button.textContent;
          button.textContent = "已复制！";
          setTimeout(() => {
            button.textContent = originalText;
          }, 2000);
        });
      }

      function resetForm() {
        document.getElementById("characterForm").reset();
        document.getElementById("realmLevel").disabled = true;
        document.getElementById("characterForm").style.display = "block";
        document.getElementById("resultContainer").classList.remove("show");
      }
    </script>
  </body>
</html>
